public class InnerOriginEndpointDashManifestConfigurationFactory(Action<Humidifier.MediaPackageV2.OriginEndpointTypes.DashManifestConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.MediaPackageV2.OriginEndpointTypes.DashManifestConfiguration>
{

    internal InnerOriginEndpointDashProgramInformationFactory ProgramInformationFactory { get; set; }

    internal InnerOriginEndpointFilterConfigurationFactory FilterConfigurationFactory { get; set; }

    internal InnerOriginEndpointDashAvailabilityStartTimeConfigurationFactory AvailabilityStartTimeConfigurationFactory { get; set; }

    internal InnerOriginEndpointDashUtcTimingFactory UtcTimingFactory { get; set; }

    internal InnerOriginEndpointDashSubtitleConfigurationFactory SubtitleConfigurationFactory { get; set; }

    internal InnerOriginEndpointDashDvbSettingsFactory DvbSettingsFactory { get; set; }

    internal InnerOriginEndpointScteDashFactory ScteDashFactory { get; set; }

    protected override Humidifier.MediaPackageV2.OriginEndpointTypes.DashManifestConfiguration Create()
    {
        var dashManifestConfigurationResult = CreateDashManifestConfiguration();
        factoryAction?.Invoke(dashManifestConfigurationResult);

        return dashManifestConfigurationResult;
    }

    private Humidifier.MediaPackageV2.OriginEndpointTypes.DashManifestConfiguration CreateDashManifestConfiguration()
    {
        var dashManifestConfigurationResult = new Humidifier.MediaPackageV2.OriginEndpointTypes.DashManifestConfiguration();

        return dashManifestConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MediaPackageV2.OriginEndpointTypes.DashManifestConfiguration result)
    {
        base.CreateChildren(result);

        result.ProgramInformation ??= ProgramInformationFactory?.Build();
        result.FilterConfiguration ??= FilterConfigurationFactory?.Build();
        result.AvailabilityStartTimeConfiguration ??= AvailabilityStartTimeConfigurationFactory?.Build();
        result.UtcTiming ??= UtcTimingFactory?.Build();
        result.SubtitleConfiguration ??= SubtitleConfigurationFactory?.Build();
        result.DvbSettings ??= DvbSettingsFactory?.Build();
        result.ScteDash ??= ScteDashFactory?.Build();
    }

} // End Of Class

